#include "breeze/model.h"

namespace breeze {

bool BreezeModel::load(const std::string & path, bool prefer_gpu) {
    backend.init(prefer_gpu);
    if (!gg.load(path, backend)) return false;
    cfg = parse_config(gg);
    if (!tok.load(gg)) return false;
    return true;
}

void BreezeModel::free() {
    gg.free();
    backend.free();
}

}
#include "breeze/model.h"
#include "breeze/backbone.h"

namespace breeze {

ReferencePrefixCache::~ReferencePrefixCache() = default;

void ReferencePrefixCache::clear() {
    cond.reset();
    uncond.reset();
    ref_text.clear();
    ref_codes.clear();
    ref_frames = 0;
    prefix_tokens = 0;
    capacity = 0;
    cfg = false;
}

BreezeModel::~BreezeModel() {
    free();
}

bool BreezeModel::load(const std::string & path, bool prefer_gpu) {
    reference_cache.clear();
    backend.init(prefer_gpu);
    if (!gg.load(path, backend)) return false;
    cfg = parse_config(gg);
    if (!tok.load(gg)) return false;
    return true;
}

void BreezeModel::free() {
    reference_cache.clear();
    gg.free();
    backend.free();
}

}

